            <section v-else class="flex min-h-[430px] flex-col overflow-hidden rounded-2xl border border-slate-200/90 bg-slate-950 shadow-inner dark:border-slate-700"><div class="flex items-center justify-between border-b border-white/10 px-3 py-1.5 text-[9px] font-bold uppercase tracking-wider text-slate-400"><span><i class="fa-solid fa-terminal mr-1 text-brand"></i>{{ store.t('Markdown clásico') }}</span><span>{{ store.t('Texto plano · sin renderizar') }} · {{ (activeSection.content || '').length }} {{ store.t('caracteres') }}</span></div><textarea ref="textareaEl" v-model="activeSection.content" aria-label="Editor Markdown sin renderizar" class="min-h-[360px] flex-1 resize-y bg-transparent p-4 font-mono text-xs leading-relaxed text-slate-100 outline-none placeholder:text-slate-500 sm:text-sm" :placeholder="store.t('Escribe aquí el contenido en Markdown para esta sección...')" spellcheck="true" @keydown="handleEditorKeydown"></textarea><div class="flex flex-wrap items-center gap-x-3 gap-y-1 border-t border-white/10 px-3 py-1.5 font-mono text-[9px] text-slate-500"><span>Tab ↹ {{ store.t('anida 1.1') }}</span><span>Shift+Tab ⇧↹ {{ store.t('asciende') }}</span><span>Ctrl/⌘+B</span><span>Ctrl/⌘+I</span><span>Enter ↵ {{ store.t('continúa') }}</span></div></section>

