-for="(item, index) in b.items" :key="index" class="flex gap-2" :style="{ paddingLeft: `${item.depth * 1.1}rem` }"><span class="font-bold text-brand">•</span><span>{{ item.text }}</span></li></ul><ol v-else-if="b.type === 'ol'" class="my-2 space-y-1 text-xs"><li v-for="(item, index) in b.items" :key="index" class="flex gap-2" :style="{ paddingLeft: `${item.depth * 1.1}rem` }"><span class="min-w-8 font-mono font-800 text-brand">{{ item.marker }}</span><span>{{ item.text }}</span></li></ol><div v-else-if="b.type === 'table'" class="my-2 overflow-x-auto rounded-xl border border-slate-200 text-xs dark:border-slate-700"><table class="w-full text-left"><thead class="bg-slate-50 dark:bg-slate-800"><tr><th v-for="(h, hIdx) in b.headers" :key="hIdx" class="p-2 font-bold">{{ h }}</th></tr></thead><tbody class="divide-y divide-slate-100 dark:divide-slate-800"><tr v-for="(row, rIdx) in b.rows" :key="rIdx"><td v-for="(cell, cIdx) in row" :key="cIdx" class="p-2 font-mono text-[11px]">{{ cell }}</td></tr></tbody></table></div><p v-else class="my-2 text-xs leading-relaxed">{{ b.text }}</p></template><div v-else class="grid h-full min-h-56 place-items-center text-center text-xs text-slate-400"><div><i class="fa-solid fa-wand-magic-sparkles mb-2 block text-xl text-brand/70"></i>{{ store.t('Write content to see it formatted here.') }}</div></div></div></aside>
          </div>
