<script>
const { ref, defineAsyncComponent, nextTick, onMounted, watch } = Vue;
const load = (p) => defineAsyncComponent(() => window["vue3-sfc-loader"].loadModule(p, window.sfcOptions));
const DocumentCoverEditor = load("./app/components/document/DocumentCoverEditor.vue?v=6");
const DocumentRichTextCanvas = load("./app/components/document/DocumentRichTextCanvas.vue?v=2");

export default {
  components: { DocumentCoverEditor, DocumentRichTextCanvas },
  props: { store: Object, activeSection: Object, activeSectionNumber: String, renderedBlocks: Array, sectionChrome: Object, suppressPageChrome: Boolean },
  emits: ["set-level", "insert-wrapper", "insert-table", "insert-prefix", "insert-callout", "insert-variable", "toggle-variable-drawer", "open-header-footer-modal", "add-root-section", "add-cover", "textarea-ready"],
  setup(props, { emit }) {
    const textareaEl = ref(null), richCanvas = ref(null), previewOpen = ref(false), authorMode = ref("visual");
    const levels = [{ value: 1, label: "H1", title: "Level 1" }, { value: 2, label: "H2", title: "Level 2" }, { value: 3, label: "H3", title: "Level 3" }];
    const registerTextarea = () => nextTick(() => emit("textarea-ready", authorMode.value === "source" ? textareaEl.value || null : null));
    onMounted(registerTextarea);
    watch(() => props.activeSection?.id, registerTextarea);
    watch(authorMode, registerTextarea);
    function setAuthorMode(mode) { if (authorMode.value === mode) return; if (authorMode.value === "visual") richCanvas.value?.commit(); authorMode.value = mode; nextTick(() => { if (mode === "source") textareaEl.value?.focus(); else { richCanvas.value?.refresh(); richCanvas.value?.focus(); } }); }
    function executeVisual(command) { richCanvas.value?.execute(command); }
    function editorValue() { return textareaEl.value?.value ?? props.activeSection?.content ?? ""; }
    function updateContent(next, start, end) { if (!props.activeSection || !textareaEl.value) return; textareaEl.value.value = next; props.activeSection.content = next; nextTick(() => { textareaEl.value.focus(); textareaEl.value.setSelectionRange(start, end == null ? start : end); }); }
    function parseOrderedLine(line) { const match = String(line || "").match(/^(\s*)((?:\d+\.)*\d+)([.)])\s+(.*)$/); return match ? { indent: match[1], path: match[2], delimiter: match[3], body: match[4] } : null; }
    function parentPathBefore(value, lineStart, childIndentLength) { const previous = value.slice(0, lineStart).split("\n"); for (let index = previous.length - 1; index >= 0; index -= 1) { const item = parseOrderedLine(previous[index]); if (item && item.indent.replace(/\t/g, "  ").length < childIndentLength) return item.path; } return ""; }
    function indentSelection(event) { const textarea = textareaEl.value, value = editorValue(), start = textarea.selectionStart, end = textarea.selectionEnd, lineStart = value.lastIndexOf("\n", Math.max(0, start - 1)) + 1, rawEnd = value.indexOf("\n", end), lineEnd = rawEnd < 0 ? value.length : rawEnd, chunk = value.slice(lineStart, lineEnd), lines = chunk.split("\n"), unindent = event.shiftKey, ordered = lines.length === 1 && parseOrderedLine(lines[0]); let nextChunk; if (ordered) { const nextIndent = unindent ? ordered.indent.replace(/(?:\t| {1,2})$/, "") : `${ordered.indent}  `; const nextPath = unindent && ordered.path.includes(".") ? ordered.path.split(".").slice(0, -1).join(".") : unindent ? ordered.path : `${parentPathBefore(value, lineStart, nextIndent.replace(/\t/g, "  ").length) || ordered.path}.1`; nextChunk = `${nextIndent}${nextPath}${ordered.delimiter} ${ordered.body}`; } else nextChunk = lines.map((line) => unindent ? line.replace(/^(?:\t| {1,2})/, "") : `  ${line}`).join("\n"); const shift = nextChunk.length - chunk.length; event.preventDefault(); updateContent(value.slice(0, lineStart) + nextChunk + value.slice(lineEnd), Math.max(lineStart, start + shift), Math.max(lineStart, end + shift)); }
    function continueList(event) { const textarea = textareaEl.value, value = editorValue(), start = textarea.selectionStart, end = textarea.selectionEnd; if (start !== end) return false; const lineStart = value.lastIndexOf("\n", Math.max(0, start - 1)) + 1, line = value.slice(lineStart, start), ordered = parseOrderedLine(line), task = line.match(/^(\s*)(- \[[ xX]\])\s+(.*)$/), bullet = line.match(/^(\s*)([-+*])\s+(.*)$/); if (!ordered && !task && !bullet) return false; event.preventDefault(); const indent = ordered?.indent ?? task?.[1] ?? bullet?.[1] ?? "", body = ordered?.body ?? task?.[3] ?? bullet?.[3] ?? ""; if (!String(body).trim()) { updateContent(value.slice(0, lineStart) + value.slice(start), lineStart); return true; } const nextPath = ordered ? ordered.path.split(".").map(Number).map((part, index, parts) => index === parts.length - 1 ? part + 1 : part).join(".") : "", marker = ordered ? `${indent}${nextPath}${ordered.delimiter} ` : task ? `${indent}- [ ] ` : `${indent}${bullet[2]} `, insert = `\n${marker}`; updateContent(value.slice(0, start) + insert + value.slice(start), start + insert.length); return true; }
    function handleEditorKeydown(event) { const shortcut = event.ctrlKey || event.metaKey; if (shortcut && !event.altKey && event.key.toLowerCase() === "b") { event.preventDefault(); emit("insert-wrapper", "**", "**", "texto en negrita"); return; } if (shortcut && !event.altKey && event.key.toLowerCase() === "i") { event.preventDefault(); emit("insert-wrapper", "*", "*", "texto en cursiva"); return; } if (event.key === "Tab") { indentSelection(event); return; } if (event.key === "Enter") continueList(event); }
    return { textareaEl, richCanvas, previewOpen, authorMode, levels, setAuthorMode, executeVisual, handleEditorKeydown };
  },
};
</script>

